#include <iostream>

class ArrayStack {
private:
    int* arr;
    int capacity;
    int topIndex;

public:
    ArrayStack(int size) {
        capacity = size;
        arr = new int[capacity];
        topIndex = -1;
    }

    ~ArrayStack() {
        delete[] arr;
    }

    void push(int val) {
        if (topIndex == capacity - 1) {
            std::cout << "Stack Overflow! Cannot push " << val << "\n";
            return;
        }
        arr[++topIndex] = val;
    }

    void pop() {
        if (topIndex == -1) {
            std::cout << "Stack Underflow! Cannot pop\n";
            return;
        }
        topIndex--;
    }

    int peek() {
        if (topIndex == -1) {
            std::cout << "Stack is empty (Underflow)\n";
            return -1;
        }
        return arr[topIndex];
    }

    bool isEmpty() {
        return topIndex == -1;
    }
};
